import pytest

from payments.validation import luhn_valid, parse_amount


def test_luhn_length_lower_boundary_12_digits_valid():
    assert luhn_valid("000000000000") is True


def test_luhn_length_11_digits_rejected():
    assert luhn_valid("00000000000") is False


def test_luhn_length_upper_boundary_19_digits_valid():
    assert luhn_valid("0" * 19) is True


def test_luhn_length_20_digits_rejected():
    assert luhn_valid("0" * 20) is False


def test_luhn_doubled_digit_five_reduces_to_one():
    # 5 at doubled position -> 10 -> 1; plus 9 gives checksum 10
    assert luhn_valid("500000000009") is True
    assert luhn_valid("500000000000") is False


def test_luhn_ignores_non_digits_with_separators():
    assert luhn_valid("5000-0000-0009") is True


def test_parse_amount_zero_is_valid():
    assert parse_amount("0") == 0.0
    assert parse_amount("0") is not None


def test_parse_amount_fraction_below_one_valid():
    assert parse_amount("0.5") == 0.5


def test_parse_amount_small_negative_rejected():
    assert parse_amount("-0.01") is None


def test_parse_amount_rounds_to_two_places():
    assert parse_amount("1.2349") == 1.23
    assert parse_amount("2.005") in (2.0, 2.01)
    assert parse_amount("7.891") == 7.89


def test_parse_amount_commas_removed():
    assert parse_amount("1,234.5") == 1234.5


def test_parse_amount_invalid_inputs_return_none():
    assert parse_amount("abc") is None
    assert parse_amount(None) is None
    assert parse_amount("") is None
